using System;
using UnityEngine;

namespace Astrea;

public class BaseJoystickInput : MonoBehaviour
{
	protected InputManager inputManager => ReferenceSingleton<InputManager>.Instance;

	protected virtual ZoomableInstance GetCurrentZoomableInstance()
	{
		return null;
	}

	public virtual void CurrentZoomableInstanceOnMouseOverExit(bool value)
	{
		if (value)
		{
			if (inputManager.IsJoystickBeingUsedDynamicInput())
			{
				GetCurrentZoomableInstance().OnMouseOver();
			}
		}
		else
		{
			GetCurrentZoomableInstance().OnMouseExit();
		}
	}

	private void OnEnable()
	{
		InputManager obj = inputManager;
		obj.OnAfterOptionPressed = (Action)Delegate.Combine(obj.OnAfterOptionPressed, new Action(OnAfterOptionPressed));
		InputManager obj2 = inputManager;
		obj2.OnAfterResumePressed = (Action)Delegate.Combine(obj2.OnAfterResumePressed, new Action(OnAfterResumePressed));
	}

	public virtual void OnAfterOptionPressed()
	{
	}

	public virtual void OnAfterResumePressed()
	{
	}

	private void OnDisable()
	{
		InputManager obj = inputManager;
		obj.OnAfterOptionPressed = (Action)Delegate.Remove(obj.OnAfterOptionPressed, new Action(OnAfterOptionPressed));
		InputManager obj2 = inputManager;
		obj2.OnAfterResumePressed = (Action)Delegate.Remove(obj2.OnAfterResumePressed, new Action(OnAfterResumePressed));
	}
}
